<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { api, token, exportReport } from './api'
import Chart from './components/Chart.vue'
import Pose from './components/Pose.vue'
import CameraTraining from './components/CameraTraining.vue'
import LandmarkReplay from './components/LandmarkReplay.vue'
import ObservationReport from './components/ObservationReport.vue'
const catalog = ref(null), cameraTraining = ref(null)

const user = ref(null), route = ref('overview'), busy = ref(false), booting = ref(true)
const loginForm = ref({ username: 'trainee', password: 'Demo123!' })
const overview = ref({ trend: [], recent_sessions: [], plans: [] }), plans = ref([]), sessions = ref([]), exercises = ref([]), trainees = ref([]), games = ref([]), database = ref(null)
const report = ref(null), reportTime = ref(0), reportPlaying = ref(false), reportFilter = ref('all')
const currentPlan = ref(null)
const planDialog = ref(false), adjustingId = ref(null), planSaving = ref(false)
const planForm = ref({ title: '', trainee_id: null, scheduled_date: '', note: '', items: [] })
const reviewDialog = ref(false), reviewForm = ref({ event_id: null, decision: 'COMMENT', note: '' })
const flowerOpen = ref(100), flowerCycles = ref(0), flowerArmed = ref(false), flowerStarted = ref(0), gameSession = ref(null), gameSaving = ref(false)
const isTrainee = computed(() => user.value?.role === 'TRAINEE'), isAdmin = computed(() => user.value?.role === 'ADMIN')
const roleName = computed(() => ({ TRAINEE: '训练者', GUIDE: '指导者', ADMIN: '管理员' }[user.value?.role] || ''))
const nav = computed(() => [
  { id: 'overview', icon: '◫', label: '训练概览' }, { id: 'plans', icon: '▦', label: isTrainee.value ? '我的训练计划' : '训练计划管理' },
  ...(isTrainee.value ? [{ id: 'training', icon: '▷', label: '摄像头跟练' }] : []),
  { id: 'reports', icon: '▤', label: isTrainee.value ? '训练报告' : '报告与指导复核' }, { id: 'library', icon: '◇', label: '训练动作库' },
  { id: 'game', icon: '✿', label: '花朵互动' }, ...(isAdmin.value ? [{ id: 'database', icon: '▥', label: '数据库概览' }] : []),
])
const titles = { overview: ['训练概览', '把每一次练习，连接成看得见的进步。'], plans: ['训练计划', '从目标设定到训练执行，清楚安排每一步。'], training: ['摄像头跟练', '观察真实动作，保留能够复核的采集记录。'], reports: ['训练报告与复核', '沿着时间轴，查看动作表现与判断依据。'], library: ['训练动作库', '三个肩肘动作，共用一套可解释的评价框架。'], game: ['让花朵慢慢绽放', '一次轻松的互动，为今天的训练收个尾。'], database: ['数据库概览', '从业务关系到真实记录，查看数据如何连接。'] }
const heading = computed(() => titles[route.value] || titles.overview)
const dateLabel = computed(() => new Date().toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }))
const published = computed(() => plans.value.filter(p => p.status === 'PUBLISHED'))
const listedReports = computed(() => sessions.value.filter(s => s.status !== 'RUNNING' && (reportFilter.value !== 'pending' || s.status === 'COMPLETED')))
const formatTime = value => { const seconds = Math.max(0, Math.floor(Number(value || 0))); return `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}` }
const shortDate = value => value ? String(value).slice(0, 10) : '—'
const dateInput = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())
const fmt = (value, digits = 0) => Number(value || 0).toFixed(digits)
const statusText = status => ({ PUBLISHED: '已发布', SUPERSEDED: '已有新版本', RUNNING: '训练中', COMPLETED: '待复核', REVIEWED: '已复核' }[status] || status)
const decisionText = decision => ({ CONFIRMED: '确认问题', REJECTED: '驳回提示', COMMENT: '总体反馈' }[decision] || decision)
const phaseText = phase => ({ CALIBRATING:'起始姿势校准', READY:'准备', UNRELIABLE:'识别不可靠，暂停计数', RAISE: '抬起 / 屈曲', HOLD: '目标区间保持', RETURN: '返回起始位置' }[phase] || '准备开始')
const safely = async fn => { try { await fn() } catch (error) { console.debug(error.message) } }
watch(route, () => window.scrollTo({ top: 0, behavior: 'instant' }), { flush: 'post' })

async function loadData() {
  if (!catalog.value) { const r = await fetch('/exercises.json'); if (!r.ok) throw new Error('动作参考目录加载失败'); catalog.value = await r.json() }
  const [o, p, s, e, g] = await Promise.all([api('/overview'), api('/plans'), api('/sessions'), api('/exercises'), api('/games')])
  overview.value = o; plans.value = p; sessions.value = s; exercises.value = e; games.value = g
  if (!isTrainee.value) trainees.value = await api('/trainees')
  if (isAdmin.value && route.value === 'database') database.value = await api('/database')
}
async function login() {
  busy.value = true
  try { const result = await api('/login', { method: 'POST', body: loginForm.value }); localStorage.setItem('rehab-token', result.token); user.value = result.user; route.value = 'overview'; await loadData() }
  catch (error) { console.debug(error.message) } finally { busy.value = false }
}
function chooseAccount(name) { loginForm.value = { username: name, password: 'Demo123!' } }
async function logout() { if (cameraTraining.value?.hasUnsaved) return ElMessage.warning('本次采集尚未保存，请先结束并保存报告'); await safely(() => api('/logout', { method: 'POST' })); clearLogin() }
function clearLogin() { localStorage.removeItem('rehab-token'); user.value = null; report.value = null; reportPlaying.value = false }
async function go(id) { if (id !== 'training' && cameraTraining.value?.hasUnsaved) return ElMessage.warning('本次采集尚未保存，请先结束并保存报告'); route.value = id; reportPlaying.value = false;  if (id === 'database') await safely(async () => { database.value = await api('/database') }) }
async function openPlan(plan) {
  if (cameraTraining.value?.hasUnsaved) return ElMessage.warning('请先保存本次采集')
  if (!isTrainee.value) return editPlan(plan)
  currentPlan.value = await api(`/plans/${plan.id}`); route.value = 'training'
}
function createPlan() {
  adjustingId.value = null
  planForm.value = { title: '肩肘基础训练', trainee_id: trainees.value[0]?.id, scheduled_date: dateInput(), note: '课程演示任务参数，实际训练请由专业人员确认。', items: exercises.value.map(e => ({ exercise_id: e.id, selected: true, sets: 1, repetitions: 6, target_min: e.target_min, target_max: e.target_max, rest_seconds: 15, hold_seconds: 0, min_duration:e.min_duration, max_duration:e.max_duration })) }
  planDialog.value = true
}
async function editPlan(plan) {
  const detail = await api(`/plans/${plan.id}`)
  adjustingId.value = detail.id
  planForm.value = { title: detail.title, trainee_id: detail.trainee_id, scheduled_date: dateInput(), note: '根据本阶段训练记录调整下一阶段任务。', items: exercises.value.map(e => { const item = detail.items.find(i => i.exercise_id === e.id); return { exercise_id: e.id, selected: !!item, sets: item?.sets || 1, repetitions: item?.repetitions || 6, target_min: item?.target_min ?? e.target_min, target_max: item?.target_max ?? e.target_max, rest_seconds: item?.rest_seconds ?? 15, hold_seconds: item?.hold_seconds ?? 0, min_duration:item?.min_duration??e.min_duration, max_duration:item?.max_duration??e.max_duration } }) }
  planDialog.value = true
}
async function savePlan() {
  const body = { ...planForm.value, items: planForm.value.items.filter(i => i.selected) }
  if (!body.title.trim() || !body.trainee_id || !body.scheduled_date || !body.items.length) return ElMessage.warning('请填写标题、训练者、日期，并至少选择一个动作')
  planSaving.value = true
  try { await api(adjustingId.value ? `/plans/${adjustingId.value}/adjust` : '/plans', { method: 'POST', body }); planDialog.value = false; await loadData(); ElMessage.success(adjustingId.value ? '新版本计划已发布，原计划保留' : '训练计划已发布') }
  catch (error) { console.debug(error.message) } finally { planSaving.value = false }
}
function sampleAt(samples, time) { if (!samples?.length) return null; let low = 0, high = samples.length - 1; while (low < high) { const mid = Math.ceil((low + high) / 2); if (samples[mid].sample_time <= time) low = mid; else high = mid - 1 } return samples[low] }
const replaySample = computed(() => { const s=sampleAt(report.value?.samples,reportTime.value);return report.value?.data_source==='CAMERA'&&s&&(reportTime.value<s.sample_time||reportTime.value-s.sample_time>.5)?null:s })
async function cameraCompleted(result) { await loadData(); await openReport(result) }
async function openReport(session) { report.value = await api(`/sessions/${session.id}`); reportTime.value = 0; reportPlaying.value = false; route.value = 'reports' }
function reviewEvent(event) { reviewForm.value = { event_id: event?.id || null, decision: event ? 'CONFIRMED' : 'COMMENT', note: '' }; reviewDialog.value = true }
async function submitReview() {
  if (!reviewForm.value.note.trim()) return ElMessage.warning('请填写反馈说明')
  busy.value = true
  try { report.value = await api(`/sessions/${report.value.id}/reviews`, { method: 'POST', body: reviewForm.value }); reviewDialog.value = false; await loadData(); ElMessage.success('复核已保存，系统原始判断保持可追溯') }
  catch (error) { console.debug(error.message) } finally { busy.value = false }
}
async function adjustFromReport() { await editPlan({ id: report.value.plan_id }) }
function seekEvent(event) { reportTime.value = event.event_time; reportPlaying.value = false }
function setFlower(value) { if (!isTrainee.value) return; if (!flowerStarted.value) flowerStarted.value = Date.now(); flowerOpen.value = Number(value); if (value <= 20) flowerArmed.value = true; if (value >= 80 && flowerArmed.value) { flowerCycles.value++; flowerArmed.value = false } }
async function saveGame() {
  if (!flowerCycles.value) return ElMessage.warning('先完成一次闭合与绽放')
  gameSaving.value = true
  try { await api('/games', { method: 'POST', body: { cycles: flowerCycles.value, duration_seconds: Math.max(1, Math.round((Date.now() - flowerStarted.value) / 1000)), session_id: gameSession.value } }); await loadData(); flowerCycles.value = 0; flowerStarted.value = 0; flowerArmed.value = false; ElMessage.success('互动记录已保存') }
  catch (error) { console.debug(error.message) } finally { gameSaving.value = false }
}

function chartBase() { return { color: ['#23866e', '#d99548'], animation: false, grid: { left: 48, right: 20, top: 25, bottom: 35 }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', axisLine: { lineStyle: { color: '#dce6df' } }, axisLabel: { color: '#7b8b82' }, axisTick: { show: false } }, yAxis: { type: 'value', axisLabel: { color: '#7b8b82' }, splitLine: { lineStyle: { color: '#edf1ed', type: 'dashed' } } } } }
const trendChart = computed(() => { const c = chartBase(); c.xAxis.data = overview.value.trend.map(t => t.date.slice(5)); c.yAxis.minInterval = 1; c.series = [{ type: 'bar', data: overview.value.trend.map(t => t.reps), barMaxWidth: 32, itemStyle: { borderRadius: [5, 5, 0, 0], color: '#4d9a80' } }]; return c })
function angleChart(data, current) { const c = chartBase(); c.xAxis.type = 'value'; c.xAxis.name = '秒'; c.yAxis.max = 180; c.yAxis.name = '幅度 °'; c.series = [{ type: 'line', showSymbol: false, data: (data || []).flatMap((s,i,a) => i&&s.sample_time-a[i-1].sample_time>.5?[[s.sample_time-.0001,null],[s.sample_time,s.angle]]:[[s.sample_time,s.angle]]), lineStyle: { width: 2.5 }, areaStyle: { color: 'rgba(35,134,110,.07)' }, markLine: { symbol: 'none', label: { show: false }, data: [{ xAxis: current }], lineStyle: { color: '#d99548' } } }]; return c }
const reportChart = computed(() => angleChart(report.value?.samples, reportTime.value))
const gamePetals = Array.from({ length: 8 }, (_, i) => i * 45)
let ticker
onMounted(async () => {
  window.addEventListener('rehab-unauthorized', clearLogin)
  if (token()) { try { user.value = await api('/me'); await loadData() } catch { clearLogin() } }
  booting.value = false
  ticker = setInterval(() => { if (reportPlaying.value && report.value) { reportTime.value = Math.min(reportTime.value + .1, report.value.duration_seconds); if (reportTime.value >= report.value.duration_seconds) reportPlaying.value = false } }, 100)
})
onBeforeUnmount(() => { clearInterval(ticker); window.removeEventListener('rehab-unauthorized', clearLogin) })
</script>

<template>
  <div v-if="booting" class="boot-screen"><span class="brand-symbol">✳</span><p>正在打开舒展工作台…</p></div>
  <main v-else-if="!user" class="login-page">
    <section class="login-story"><div class="brand"><span class="brand-symbol">✳</span><div>舒展<span>REHAB STUDIO</span></div></div><div class="login-copy"><span class="eyebrow">每一次练习，都值得被看见</span><h1>从容练习，<br>清楚看见每一步。</h1><p>让计划、动作反馈与指导复核连接起来。<br>一个围绕训练过程展开的康复辅助平台。</p><div class="login-illustration"><Pose :angle="72" compact/><span class="floating-note">↗ 计划 · 跟练 · 反馈 · 复核</span></div></div><small>数据库课程原型 · 摄像头版 0.2</small></section>
    <section class="login-form-area"><div class="login-box"><span class="eyebrow">欢迎来到舒展</span><h2>登录训练工作台</h2><p class="muted">选择演示身份，体验一条完整的训练流程。</p><div class="account-options"><button v-for="account in [['trainee','训练者','张同学'],['teacher','指导者','林老师'],['admin','管理员','数据库']]" :key="account[0]" :class="{selected:loginForm.username===account[0]}" @click="chooseAccount(account[0])"><b>{{account[1]}}</b><small>{{account[2]}}</small></button></div><el-form label-position="top" @submit.prevent="login"><el-form-item label="账号"><el-input v-model="loginForm.username" size="large" placeholder="请输入账号" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="loginForm.password" type="password" show-password size="large" autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-button type="primary" size="large" class="full" :loading="busy" @click="login">进入工作台　→</el-button></el-form><div class="login-tip">演示密码统一为 <b>Demo123!</b><br>摄像头记录真实动作；历史模拟记录保留来源标识。</div></div></section>
  </main>

  <div v-else class="app-shell">
    <aside class="sidebar"><div class="brand"><span class="brand-symbol">✳</span><div>舒展<span>REHAB STUDIO</span></div></div><div class="workspace-label">训练工作台</div><nav><button v-for="item in nav" :key="item.id" :class="{active:route===item.id}" @click="go(item.id)"><span>{{item.icon}}</span>{{item.label}}<i v-if="item.id==='reports'&&overview.pending_reviews" class="nav-dot"></i></button></nav><div class="sidebar-note"><span>✦</span><b>循序渐进，认真记录</b><p>每个动作都有反馈，<br>每次训练都能回顾。</p><small>课程原型 · 摄像头观察</small></div><button class="user-panel" @click="logout" title="退出并切换演示身份"><span class="avatar">{{user.display_name.slice(0,1)}}</span><div><b>{{user.display_name}}</b><small>{{roleName}} · 退出登录</small></div><span>↗</span></button></aside>
    <div class="main-shell"><header class="topbar"><div><span class="breadcrumb">舒展工作台</span><span class="crumb-slash">/</span>{{heading[0]}}</div><div class="topbar-right"><span class="demo-badge"><i></i>0.2 · 姿态观察</span><span>{{dateLabel}}</span><button class="mobile-logout" @click="logout">{{user.display_name}} · 退出</button></div></header>
      <main class="workspace"><div class="page-heading"><div><div class="eyebrow">{{isTrainee?'YOUR REHAB JOURNEY':'TRAINING WORKSPACE'}}</div><h1>{{heading[0]}}</h1><p>{{heading[1]}}</p></div><el-button v-if="!isTrainee && ['overview','plans'].includes(route)" type="primary" size="large" @click="createPlan">＋ 发布训练计划</el-button><el-button v-else-if="route==='overview'" type="primary" size="large" @click="go('plans')">查看训练计划　↗</el-button></div>

      <template v-if="route==='overview'"><div class="section-note"><span>◫</span><p>下方为历史业务汇总，包含旧版模拟记录。动作次数和计划完成率不表示疗效，具体来源与是否评价目标请查看每份报告。</p></div>
        <section class="welcome-banner"><div><span class="eyebrow">{{isTrainee?'TODAY IS A GOOD DAY TO BEGIN':'CONNECTED CARE, CLEAR PROGRESS'}}</span><h2>{{isTrainee?'你好，'+user.display_name+'。按自己的节奏开始。':'你好，'+user.display_name+'。让指导有迹可循。'}}</h2><p>{{isTrainee?'今天的目标，是认真完成每一次练习。':'查看训练记录，复核问题，安排下一阶段任务。'}}</p><button class="text-button" @click="go(isTrainee?'plans':'reports')">{{isTrainee?'开始今天的训练':'查看待复核记录'}}　→</button></div><div class="banner-art"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="banner-flower">✳</span><small>SHARE YOUR PROGRESS</small></div></section>
        <section class="stat-grid"><article class="stat-card"><span class="stat-icon green">▦</span><div><p>到期计划完成率</p><strong>{{overview.completion_rate||0}}<small>%</small></strong><span>{{overview.completed_plans||0}} / {{overview.due_count||0}} 项到期计划</span></div></article><article class="stat-card"><span class="stat-icon sand">▷</span><div><p>已完成训练</p><strong>{{overview.session_count||0}}<small>次</small></strong><span>完整会话记录</span></div></article><article class="stat-card"><span class="stat-icon blue">⌁</span><div><p>计划指标满足次数</p><strong>{{overview.valid_reps||0}}<small>次</small></strong><span>共 {{overview.total_reps||0}} 次已记录动作</span></div></article><article class="stat-card"><span class="stat-icon rose">▤</span><div><p>等待指导复核</p><strong>{{overview.pending_reviews||0}}<small>份</small></strong><span>保留判断依据与问题时间点</span></div></article></section>
        <div class="overview-columns"><section class="panel"><div class="panel-heading"><div><h3>近期训练计划</h3><p>一次只专注一个清楚的目标</p></div><button class="text-button" @click="go('plans')">全部计划 →</button></div><div v-if="!published.length" class="empty-state">暂无计划，等待指导者发布。</div><article v-for="(plan,i) in published.slice(0,2)" :key="plan.id" class="compact-plan"><div class="exercise-icon">{{i?'◇':'⌁'}}</div><div class="compact-plan-body"><span class="mini-label">{{shortDate(plan.scheduled_date)}} · V{{plan.version}}</span><h4>{{plan.title}}</h4><p>{{plan.exercise_count}} 个动作 · {{plan.trainee_name}}</p></div><el-button :type="i?'default':'primary'" @click="safely(()=>openPlan(plan))">{{isTrainee?'进入训练':'调整计划'}}</el-button></article></section><section class="panel"><div class="panel-heading"><div><h3>近 7 天训练次数</h3><p>以实际保存的动作记录统计</p></div><span class="mini-label">次</span></div><Chart :option="trendChart" height="220px"/></section></div>
        <section class="panel"><div class="panel-heading"><div><h3>最近训练记录</h3><p>从每份报告中找到下一步</p></div><button class="text-button" @click="go('reports')">查看全部 →</button></div><div v-if="!overview.recent_sessions.length" class="empty-state"><span>▤</span><b>第一份训练报告，等你开始</b><p>进入计划并完成摄像头跟练，即可查看问题回放与分项结果。</p></div><div v-else class="session-row" v-for="s in overview.recent_sessions" :key="s.id"><div class="row-icon">▤</div><div class="grow"><b>{{s.title}}</b><p>{{s.trainee_name}} · {{shortDate(s.started_at)}} · {{s.total_reps}} 次动作</p></div><span class="status-pill" :class="s.status.toLowerCase()">{{statusText(s.status)}}</span><button class="text-button" @click="safely(()=>openReport(s))">查看报告 ↗</button></div></section>
      </template>

      <template v-else-if="route==='plans'">
        <div class="section-note"><span>◷</span><p>已发布计划与训练结果分开保存。调整计划会生成新版本，历史训练继续关联原始要求。</p></div><div v-if="!plans.length" class="panel empty-state">暂无训练计划。</div><div class="plan-grid"><article class="panel plan-card" v-for="plan in plans" :key="plan.id"><div class="plan-card-top"><span class="exercise-icon">⌁</span><span class="status-pill" :class="plan.status.toLowerCase()">{{statusText(plan.status)}}</span></div><span class="mini-label">PLAN {{String(plan.id).padStart(3,'0')}} · VERSION {{plan.version}}</span><h3>{{plan.title}}</h3><p class="muted">{{plan.note}}</p><div class="plan-meta"><span>训练者 <b>{{plan.trainee_name}}</b></span><span>安排日期 <b>{{shortDate(plan.scheduled_date)}}</b></span><span>动作数量 <b>{{plan.exercise_count}} 项</b></span><span>完成会话 <b>{{plan.completed_sessions}} 次</b></span></div><el-button class="full" :type="plan.status==='PUBLISHED'?'primary':'default'" :disabled="plan.status!=='PUBLISHED'" @click="safely(()=>openPlan(plan))">{{isTrainee?'查看要求并开始训练':'调整下一阶段计划'}}　→</el-button></article></div>
      </template>

      <template v-else-if="route==='training'">
        <div v-if="!currentPlan" class="panel empty-state"><b>先选择一个训练计划</b><p>根据具体动作调整机位，默认只记录动作表现。</p><el-button type="primary" @click="go('plans')">前往我的计划</el-button></div>
        <CameraTraining v-else ref="cameraTraining" :key="currentPlan.id" :plan="currentPlan" :catalog="catalog" @completed="cameraCompleted"/>
      </template>

      <template v-else-if="route==='reports'">
        <template v-if="!report"><div class="filter-bar"><el-radio-group v-model="reportFilter"><el-radio-button value="all">全部报告</el-radio-button><el-radio-button value="pending">等待复核</el-radio-button></el-radio-group><span class="muted">{{listedReports.length}} 份报告</span></div><section class="panel"><div v-if="!listedReports.length" class="empty-state"><span>▤</span><b>这里还没有训练报告</b><p>完成一次摄像头训练后，报告和问题事件会自动出现。</p></div><el-table v-else :data="listedReports" @row-click="s=>safely(()=>openReport(s))" class="clickable-table"><el-table-column label="训练计划" min-width="200"><template #default="{row}"><b>{{row.title}}</b><small class="cell-sub">SESSION {{row.id}} · {{row.trainee_name}}</small></template></el-table-column><el-table-column label="训练日期" min-width="120"><template #default="{row}">{{shortDate(row.started_at)}}</template></el-table-column><el-table-column label="来源" width="110"><template #default="{row}">{{row.data_source==='CAMERA'?'摄像头':'历史模拟'}}</template></el-table-column><el-table-column prop="total_reps" label="动作次数" width="100"/><el-table-column prop="valid_reps" label="计划指标满足" width="130"><template #default="{row}">{{row.data_source==='CAMERA'?'见报告':row.valid_reps}}</template></el-table-column><el-table-column prop="issue_count" label="问题提示" width="100"/><el-table-column label="状态" width="110"><template #default="{row}"><span class="status-pill" :class="row.status.toLowerCase()">{{statusText(row.status)}}</span></template></el-table-column><el-table-column width="90"><template #default>查看 ↗</template></el-table-column></el-table></section></template>
        <template v-else><div class="report-toolbar"><button class="text-button" @click="report=null;reportPlaying=false">← 返回报告列表</button><div class="button-row"><el-button @click="exportReport(report.id)">导出 CSV</el-button><el-button v-if="!isTrainee" @click="safely(adjustFromReport)">调整后续计划</el-button><el-button v-if="!isTrainee" type="primary" @click="reviewEvent(null)">添加总体反馈</el-button></div></div><section class="panel report-summary"><div><span class="mini-label">TRAINING REPORT / {{String(report.id).padStart(3,'0')}} · {{report.data_source==='CAMERA'?'摄像头采集':'历史模拟数据'}}</span><h2>{{report.title}}</h2><p class="muted">{{report.trainee_name}} · {{shortDate(report.started_at)}} · {{report.algorithm_version}}</p></div><div class="report-numbers"><div><strong>{{report.total_reps}}</strong><span>完成动作</span></div><div><strong>{{report.assessment?.evaluation_mode==='OBSERVATION'?'—':report.valid_reps}}</strong><span>{{report.assessment?.evaluation_mode==='OBSERVATION'?'目标指标未评价':'计划指标满足'}}</span></div><div><strong class="amber">{{report.issue_count}}</strong><span>问题提示</span></div><span class="status-pill" :class="report.status.toLowerCase()">{{statusText(report.status)}}</span></div></section>
        <ObservationReport :report="report"/><div class="replay-grid"><section class="panel replay-panel"><div class="panel-heading"><div><h3>骨架与角度回放</h3><p>{{replaySample?.exercise_name||'点击右侧问题定位时刻'}}</p></div><span class="mini-label">{{formatTime(reportTime)}}</span></div><div class="replay-content"><LandmarkReplay v-if="report.data_source==='CAMERA'" :sample="replaySample"/><Pose v-else :angle="replaySample?.angle||0" :trunk="replaySample?.trunk_offset||0" :code="replaySample?.exercise_code" compact/><div class="replay-readings"><strong>{{replaySample?.angle==null?'—':fmt(replaySample.angle)}}°</strong><p>{{report.assessment?.evaluation_mode==='OBSERVATION'?'仅记录模式 · 未比较目标':`计划目标 ${replaySample?.target_min}–${replaySample?.target_max}°`}}</p><span>{{replaySample?phaseText(replaySample.phase):'当前时段无采集数据'}}</span></div></div><div class="replay-controls"><el-button circle @click="reportPlaying=!reportPlaying">{{reportPlaying?'Ⅱ':'▷'}}</el-button><el-slider v-model="reportTime" :max="report.duration_seconds||1" :step="0.1" :format-tooltip="formatTime" @change="reportPlaying=false"/><span>{{formatTime(report.duration_seconds)}}</span></div><Chart :option="reportChart" height="200px"/></section><section class="panel event-panel"><div class="panel-heading"><div><h3>问题时间点</h3><p>点击定位，查看触发依据</p></div><span class="count-badge">{{report.events.length}}</span></div><div v-if="!report.events.length" class="empty-state"><span>✓</span><b>本次未生成规则问题提示</b></div><article v-for="event in report.events" :key="event.id" class="event-item" :class="{selected:Math.abs(reportTime-event.event_time)<.2}" @click="seekEvent(event)"><div class="event-title"><span>{{formatTime(event.event_time)}}</span><b>{{{AMPLITUDE:'幅度未达目标',TEMPO:'节奏偏差',TRUNK:'躯干偏移',HOLD:'保持未达要求'}[event.code]}}</b><button v-if="!isTrainee" @click.stop="reviewEvent(event)">复核</button></div><p>{{event.message}}</p><small>观察值 {{fmt(event.observed,1)}} · 要求 {{event.threshold_value}}</small><span v-if="report.reviews.find(r=>r.event_id===event.id)" class="reviewed-label">{{decisionText(report.reviews.find(r=>r.event_id===event.id).decision)}}</span></article></section></div>
        <section class="panel"><div class="panel-heading"><div><h3>每次动作的分项结果</h3><p>分别评价幅度、节奏、躯干与保持，不合成为随机分数</p></div></div><el-table :data="report.repetitions" max-height="380"><el-table-column prop="exercise_name" label="动作" min-width="150"/><el-table-column label="组 / 次" width="95"><template #default="{row}">{{row.set_index}} / {{row.rep_index}}</template></el-table-column><el-table-column label="峰值幅度" width="110"><template #default="{row}">{{fmt(row.peak_angle,1)}}°</template></el-table-column><el-table-column label="耗时" width="90"><template #default="{row}">{{fmt(row.duration_seconds,1)}} 秒</template></el-table-column><el-table-column v-for="column in [['amplitude_ok','幅度'],['tempo_ok','节奏'],['trunk_ok','躯干'],['hold_ok','保持']]" :key="column[0]" :label="column[1]" min-width="90"><template #default="{row}"><span :class="row[column[0]]==null?'muted':row[column[0]]?'ok-text':'warn-text'">{{row[column[0]]==null?'未评价':row[column[0]]?'符合计划':'需复核'}}</span></template></el-table-column></el-table></section>
        <section class="panel"><div class="panel-heading"><div><h3>指导反馈与修改留痕</h3><p>系统原始结果与人工意见分别保存</p></div></div><div v-if="!report.reviews.length" class="empty-state compact">指导者尚未添加反馈。</div><article v-for="review in report.reviews" :key="review.id" class="review-item"><span class="avatar small">{{review.guide_name.slice(0,1)}}</span><div><b>{{review.guide_name}} <span class="mini-label">{{decisionText(review.decision)}}{{review.event_id?' · 事件 #'+review.event_id:''}}</span></b><p>{{review.note}}</p><small>{{String(review.created_at).replace('T',' ').slice(0,19)}}</small></div></article></section></template>
      </template>

      <template v-else-if="route==='library'"><div class="section-note"><span>◇</span><p>{{catalog?.scope}}</p></div><div class="library-grid"><article v-for="exercise in catalog?.exercises" :key="exercise.code" class="panel exercise-card"><div class="exercise-card-body"><span class="mini-label">UPPER LIMB / 有来源的动作说明</span><h3>{{exercise.name}}</h3><p class="camera-view">{{exercise.view}}</p><ol class="motion-steps"><li v-for="step in exercise.steps" :key="step">{{step}}</li></ol><p>{{exercise.measurement}}</p><a :href="exercise.source.url" target="_blank" rel="noopener noreferrer">查看官方动作图示与说明 ↗</a><p class="source-label">{{exercise.source.title}} · {{exercise.source.section}}</p><p class="mini-note">{{exercise.caution}}</p></div></article></div><p class="mini-note">{{catalog?.rules_note}}</p></template>

      <template v-else-if="route==='game'"><div class="section-note"><span>✿</span><p>第一版使用鼠标或空格键模拟开合输入，尚未接入手势识别。一次闭合后重新绽放记为一个循环。</p></div><div class="game-grid"><section class="flower-garden" tabindex="0" @pointerdown.prevent="setFlower(0)" @pointerup="setFlower(100)" @pointerleave="isTrainee&&flowerStarted&&setFlower(100)" @keydown.space.prevent="setFlower(0)" @keyup.space.prevent="setFlower(100)"><span class="garden-label">A LITTLE MOMENT OF CALM</span><svg viewBox="0 0 360 400" class="flower-svg" aria-label="按住闭合，松开绽放的花朵"><ellipse cx="180" cy="362" rx="88" ry="10" fill="#cbdccb"/><path d="M180 180Q169 275 180 355" fill="none" stroke="#58926b" stroke-width="9"/><path d="M176 292Q101 290 112 247Q163 240 176 292" fill="#8bb18b"/><path d="M177 321Q250 310 239 267Q188 270 177 321" fill="#a8c5a0"/><g transform="translate(30 5)"><g v-for="degree in gamePetals" :key="degree" :transform="`rotate(${degree} 150 150)`"><ellipse cx="150" :cy="150-(flowerOpen/100*40+8)" :rx="14+flowerOpen/100*15" :ry="24+flowerOpen/100*25" :fill="degree%90===0?'#dfb09c':'#eac2ad'" opacity=".95"/></g><circle cx="150" cy="150" :r="17+flowerOpen/100*6" fill="#e8c777"/><circle cx="144" cy="144" r="4" fill="#f1db9a"/></g></svg><h2>{{flowerOpen>=80?'慢慢绽放':'轻轻闭合'}}</h2><p>{{isTrainee?'按住鼠标或空格键闭合，松开后绽放':'切换到训练者账号即可体验互动并保存记录'}}</p></section><section class="panel game-controls"><span class="mini-label">AUXILIARY TRAINING / 辅助互动</span><h3>给练习一点轻松的节奏</h3><p class="muted">不计动作质量分数，记录真实互动次数和时长。</p><div class="game-counter"><strong>{{flowerCycles}}</strong><span>已完成开合循环</span></div><label>花朵开放程度</label><el-slider :model-value="flowerOpen" :disabled="!isTrainee" @update:model-value="setFlower"/><el-select v-model="gameSession" clearable placeholder="可选：关联本次训练" class="full" :disabled="!isTrainee"><el-option v-for="s in sessions.filter(s=>s.status!=='RUNNING')" :key="s.id" :value="s.id" :label="`#${s.id} ${s.title}`"/></el-select><el-button type="primary" size="large" class="full" :disabled="!isTrainee||!flowerCycles" :loading="gameSaving" @click="saveGame">保存本次互动</el-button></section></div><section class="panel"><div class="panel-heading"><div><h3>最近互动记录</h3><p>游戏作为附加模块，与训练记录按需关联</p></div></div><el-table :data="games" empty-text="还没有互动记录"><el-table-column prop="trainee_name" label="训练者"/><el-table-column prop="cycles" label="开合次数"/><el-table-column label="时长"><template #default="{row}">{{row.duration_seconds}} 秒</template></el-table-column><el-table-column label="关联会话"><template #default="{row}">{{row.session_id?'#'+row.session_id:'独立互动'}}</template></el-table-column><el-table-column label="输入方式"><template #default>鼠标 / 键盘模拟</template></el-table-column><el-table-column label="日期"><template #default="{row}">{{shortDate(row.created_at)}}</template></el-table-column></el-table></section></template>

      <template v-else-if="route==='database'"><div class="section-note"><span>▥</span><p>17 张表连接用户、计划、训练、证据和反馈。下方数据直接查询当前数据库；刷新可观察训练后的记录变化。</p></div><section class="panel" v-if="database"><div class="panel-heading"><div><h3>数据表与记录数</h3><p>{{database.notes}}</p></div><el-button @click="go('database')">刷新数据</el-button></div><div class="database-grid"><article v-for="table in database.tables" :key="table.table"><span>{{table.name}}</span><strong>{{table.count}}</strong><code>{{table.table}}</code></article></div><div class="sql-example"><h3>索引查询示例</h3><pre>{{database.query}}</pre><p class="muted">训练者与时间组成复合索引，帮助历史记录查询。实际执行计划如下：</p><pre>{{JSON.stringify(database.explain,null,2)}}</pre></div></section></template>
      <footer class="page-footer"><span>舒展 · 康复训练辅助平台</span><span>课程研究原型 · 不提供诊断或疗效判断</span></footer>
      </main>
    </div>

    <el-dialog v-model="planDialog" :title="adjustingId?'调整并发布下一版本':'发布训练计划'" width="min(940px,94vw)" destroy-on-close><el-form label-position="top"><div class="form-grid"><el-form-item label="计划名称"><el-input v-model="planForm.title" maxlength="100"/></el-form-item><el-form-item label="训练者"><el-select v-model="planForm.trainee_id" :disabled="!!adjustingId" class="full"><el-option v-for="t in trainees" :key="t.id" :label="t.display_name" :value="t.id"/></el-select></el-form-item><el-form-item label="安排日期"><el-date-picker v-model="planForm.scheduled_date" value-format="YYYY-MM-DD" type="date" class="full"/></el-form-item></div><div class="plan-item-editor" v-for="item in planForm.items" :key="item.exercise_id"><el-checkbox v-model="item.selected"><b>{{exercises.find(e=>e.id===item.exercise_id)?.name}}</b></el-checkbox><div class="item-fields" v-if="item.selected"><label>组数<el-input-number v-model="item.sets" :min="1" :max="5" size="small"/></label><label>每组次数<el-input-number v-model="item.repetitions" :min="1" :max="20" size="small"/></label><label>最小幅度 °<el-input-number v-model="item.target_min" :min="0" :max="179" size="small"/></label><label>最大幅度 °<el-input-number v-model="item.target_max" :min="1" :max="180" size="small"/></label><label>循环最短 秒<el-input-number v-model="item.min_duration" :min="0.6" :max="30" :step="0.5" size="small"/></label><label>循环最长 秒<el-input-number v-model="item.max_duration" :min="0.6" :max="30" :step="0.5" size="small"/></label><label>保持 秒<el-input-number v-model="item.hold_seconds" :min="0" :max="10" size="small"/></label><label>组间休息 秒<el-input-number v-model="item.rest_seconds" :min="0" :max="300" size="small"/></label></div></div><el-form-item :label="adjustingId?'调整原因与指导说明':'训练说明'"><el-input v-model="planForm.note" type="textarea" :rows="2" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="planDialog=false">取消</el-button><el-button type="primary" :loading="planSaving" @click="savePlan">{{adjustingId?'发布新版本':'发布计划'}}</el-button></template></el-dialog>
    <el-dialog v-model="reviewDialog" title="指导者复核与反馈" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="复核对象"><el-input :model-value="reviewForm.event_id?'问题事件 #'+reviewForm.event_id:'本次训练总体反馈'" disabled/></el-form-item><el-form-item label="复核决定"><el-radio-group v-model="reviewForm.decision"><el-radio value="CONFIRMED" :disabled="!reviewForm.event_id">确认问题</el-radio><el-radio value="REJECTED" :disabled="!reviewForm.event_id">驳回提示</el-radio><el-radio value="COMMENT">补充说明</el-radio></el-radio-group></el-form-item><el-form-item label="反馈说明"><el-input v-model="reviewForm.note" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="记录判断依据、观察结果或下一步建议"/></el-form-item></el-form><template #footer><el-button @click="reviewDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitReview">保存复核记录</el-button></template></el-dialog>
  </div>
</template>
